"""Personal promises of the eighteen heroes, indexed by the printed hero ID."""
from typing import NamedTuple


class Branch(NamedTuple):
    label: str
    scene: str
    reply: str
    epilogue: str


class Quest(NamedTuple):
    title: str
    realm: int
    reply_realm: int
    offer: str
    meeting: str
    paths: dict[str, Branch]
    unfinished: str


